class ServeConfig(BaseModel):
    """Picklable server settings for Sanic worker AppLoader factories."""

    model_config = ConfigDict(frozen=True)

    enable_api: bool = True
    cors: Text | List[Text] | None = None
    auth_token: Optional[SecretStr] = None
    response_timeout: int = constants.DEFAULT_RESPONSE_TIMEOUT
    keep_alive_timeout: int = constants.DEFAULT_KEEP_ALIVE_TIMEOUT
    jwt_secret: Optional[SecretStr] = None
    jwt_private_key: Optional[SecretStr] = None
    jwt_method: Optional[Text] = None
    endpoints_path: Optional[Text] = None
    endpoints_snapshot: Optional[Dict[str, Any]] = Field(default=None, repr=False)
    credentials_path: Optional[Text] = None
    sub_agents_path: Optional[Text] = None
    connector: Optional[Text] = None
    route: Optional[Text] = constants.DEFAULT_WEBHOOKS_PATH
    port: int = constants.DEFAULT_SERVER_PORT
    conversation_id: Optional[Text] = None
    request_timeout: Optional[int] = None
    model_path: Optional[Text] = None
    remote_storage: Optional[StorageType] = None
    log_file: Optional[Text] = None
    use_syslog: bool = False
    syslog_address: Optional[Text] = None
    syslog_port: Optional[int] = None
    syslog_protocol: Optional[Text] = None
    logging_config_file: Optional[Text] = None
    log_level: Optional[int] = None
    use_uvloop: bool = False
    is_inspector_enabled: bool = False
    inspector_voice: bool = False
    inspector_legacy: bool = False
    inspector_server_url: Optional[Text] = None
    open_inspector_in_browser: bool = False
    ssl_certificate: Optional[Text] = None
    ssl_keyfile: Optional[Text] = None
    ssl_ca_file: Optional[Text] = None
    ssl_password: Optional[SecretStr] = None
    observability: Optional[ObservabilitySettings] = None


def build_serve_config(
    *,
    credentials: Optional[CredentialsConfig] = None,
    endpoints: Optional[AvailableEndpoints] = None,
    **fields: Any,
) -> ServeConfig:
    """Build a picklable ``ServeConfig`` from runtime objects and path fields.

    Scalar serve settings are accepted via ``**fields`` and mapped onto
    ``ServeConfig``. Plain-text secrets (``auth_token``, ``jwt_secret``,
    ``jwt_private_key``, ``ssl_password``) are wrapped as ``SecretStr``.
    """
    endpoints_path = (
        str(endpoints.config_file_path)
        if endpoints is not None and endpoints.config_file_path is not None
        else None
    )
    endpoints_snapshot = (
        endpoints.to_dict()
        if endpoints is not None and endpoints.config_file_path is None
        else None
    )
    credentials_path = (
        str(credentials.config_file_path)
        if credentials is not None and credentials.config_file_path is not None
        else None
    )
    auth_token = fields.pop("auth_token", None)
    jwt_secret = fields.pop("jwt_secret", None)
    jwt_private_key = fields.pop("jwt_private_key", None)
    ssl_password = fields.pop("ssl_password", None)
    conversation_id = fields.pop("conversation_id", None)
    return ServeConfig(
        **fields,
        endpoints_path=endpoints_path,
        endpoints_snapshot=endpoints_snapshot,
        credentials_path=credentials_path,
        auth_token=SecretStr(auth_token) if auth_token else None,
        jwt_secret=SecretStr(jwt_secret) if jwt_secret else None,
        jwt_private_key=SecretStr(jwt_private_key) if jwt_private_key else None,
        ssl_password=SecretStr(ssl_password) if ssl_password else None,
        conversation_id=conversation_id or uuid.uuid4().hex,
    )


def _secret_value(value: Optional[SecretStr]) -> Optional[Text]:
    return value.get_secret_value() if value is not None else None


class _RasaCertLoader(CertLoader):
    """Rebuild TLS contexts in spawn workers via ``server.create_ssl_context``.

    Sanic ships only the picklable ``.sanic`` path dict across the spawn boundary;
    this loader reconstructs the same context each worker used to serve with.
    """

    def load(self, app: Sanic) -> Optional["SSLContext"]:
        """Load an SSL context from certificate path data."""
        if not isinstance(self._ssl_data, dict):
            return None
        certificate = self._ssl_data.get("cert")
        if not certificate:
            return None
        keyfile = self._ssl_data.get("key")
        ca_file = self._ssl_data.get("ca")
        password = self._ssl_data.get("password")
        return server.create_ssl_context(
            str(certificate),
            str(keyfile) if keyfile is not None else None,
            str(ca_file) if ca_file is not None else None,
            str(password) if password is not None else None,
        )


def _build_worker_ssl(config: ServeConfig) -> Optional["SSLContext"]:
    """Build a Sanic-shippable SSL context from picklable certificate paths.

    A plain ``ssl.SSLContext`` cannot be pickled under spawn. Sanic only replaces
    ``kwargs['ssl']`` with picklable path data when the object is a
    ``SanicSSLContext`` carrying a ``.sanic`` dict — see Sanic's
    ``Sanic.serve`` worker kwargs conversion.
    """
    if not config.ssl_certificate:
        return None

    context = server.create_ssl_context(
        config.ssl_certificate,
        config.ssl_keyfile,
        config.ssl_ca_file,
        _secret_value(config.ssl_password),
    )
    if context is None:
        return None

    sanic_context = SanicSSLContext.create_from_ssl_context(context)
    sanic_context.sanic = {
        "cert": config.ssl_certificate,
        "key": config.ssl_keyfile,
        "ca": config.ssl_ca_file,
        "password": _secret_value(config.ssl_password),
    }
    return sanic_context


def _bootstrap_serve_process(config: ServeConfig) -> None:
    """Re-run process bootstrap that ``rasa.__main__.main`` normally owns.

    Spawn workers do not execute the CLI ``main()`` guard, so logging, license
    checks, and ``Configuration`` must be reconstructed inside the factory.
    Logging mirrors ``main()``: CLI log level (``-v``/``-vv``/``--quiet``) and
    ``--logging-config-file`` are re-applied from ``ServeConfig``.
    """
    if os.getcwd() not in sys.path:
        sys.path.insert(1, os.getcwd())

    configure_logging_and_warnings(
        config.log_level,
        config.logging_config_file,
        warn_only_once=True,
        filter_repeated_logs=True,
    )
    # Match main(): None → env default inside configure_colored_logging.
    colored_level = (
        logging.getLevelName(config.log_level) if config.log_level is not None else None
    )
    rasa.utils.io.configure_colored_logging(colored_level)
    configure_structlog(config.log_level)
    licensing.validate_license_from_env()
    _configure_serve_observability(config.observability)

    if config.endpoints_path:
        Configuration.initialise_endpoints(
            Path(config.endpoints_path),
            model_path=config.model_path,
        )
    elif config.endpoints_snapshot is not None:
        Configuration.initialise_endpoints_from_object(
            AvailableEndpoints.from_dict(config.endpoints_snapshot)
        )
    else:
        Configuration.initialise_empty_endpoints()

    if config.credentials_path:
        Configuration.initialise_credentials(
            Path(config.credentials_path),
            model_path=config.model_path,
        )

    if config.sub_agents_path:
        Configuration.initialise_sub_agents(Path(config.sub_agents_path))
    else:
        Configuration.initialise_sub_agents(None)

    _register_serve_secrets_manager(config.endpoints_path, config.model_path)


def _configure_serve_observability(
    settings: Optional[ObservabilitySettings],
) -> None:
    """Apply the parent's tracing, metrics, and Langfuse settings in a worker.

    The CLI parent configures observability in ``configure_commandline`` and
    ships what it applied in ``ServeConfig``. The parent also runs this
    factory, where the settings are already applied and are skipped so no
    second set of exporters is started. Programmatic serves that never
    configured observability ship ``None`` and stay unconfigured.
    """
    if settings is None or applied_process_observability() is not None:
        return
    configure_process_observability(settings)


def _register_serve_secrets_manager(
    endpoints_path: Optional[Text],
    model_path: Optional[Text] = None,
) -> None:
    """Register the secrets manager in a process that did not run the CLI.

    ``rasa`` registers it from ``__main__`` before the command runs. Spawn
    workers skip that path, so a Vault-backed tracker store would fail inside
    the worker. A process that already has a manager keeps it: constructing
    ``VaultSecretsManager`` again would start a second token renewal job.
    """
    from rasa.core.secrets_manager.secret_manager import SecretsManagerProvider
    from rasa.plugin import plugin_manager

    if SecretsManagerProvider().secret_managers:
        return
    plugin_manager().hook.init_managers(
        endpoints_file=endpoints_path,
        model_path=model_path,
    )


def _reset_uvloop_event_loop_policy() -> None:
    """Drop a uvloop policy installed by an import before Sanic creates the loop."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", DeprecationWarning)
        policy = asyncio.get_event_loop_policy()
        if not type(policy).__module__.startswith("uvloop"):
            return
        asyncio.set_event_loop_policy(None)


def _apply_runtime_app_settings(app: Sanic, config: ServeConfig) -> None:
    app.config.KEEP_ALIVE_TIMEOUT = config.keep_alive_timeout
    if config.use_uvloop and not _is_apple_silicon_system():
        app.config.USE_UVLOOP = True
        structlogger.debug("serve.event_loop.configured", use_uvloop=True)
        return

    # Sanic 25 setup_loop() installs uvloop unless this is a real False.
    # Pre-upgrade legacy serve never did; uvloop then crashes on C TLS /
    # SDK thread boundaries. See ENG-667.
    app.config.USE_UVLOOP = False
    _reset_uvloop_event_loop_policy()
    structlogger.debug("serve.event_loop.configured", use_uvloop=False)


def _register_input_channels(
    app: Sanic,
    input_channels: List[InputChannel],
    route: Optional[Text],
) -> None:
    if input_channels:
        channels.channel.register(input_channels, app, route=route)
    if logger.isEnabledFor(logging.DEBUG):
        rasa.core.utils.list_routes(app)


def _configure_async_logging(running_app: Sanic) -> None:
    if logger.isEnabledFor(logging.DEBUG):
        rasa.utils.io.enable_async_loop_debugging(asyncio.get_running_loop())


async def _run_cmdline_io(config: ServeConfig, running_app: Sanic) -> None:
    """Shut down the server once cmdline IO finishes."""
    await console.record_messages(
        server_url=constants.DEFAULT_SERVER_FORMAT.format("http", config.port),
        sender_id=config.conversation_id,
        request_timeout=config.request_timeout,
        # Collect complete utterances. Token streaming via ``stream=true``
        # yields one NDJSON line per chunk, which the console would print
        # as separate messages (one word/token per line).
        use_response_stream=False,
    )
    logger.info("Killing Sanic server now.")
    running_app.stop()


def _channel_names(input_channels: List[InputChannel]) -> set[Text]:
    return {channel.name() for channel in input_channels}


_MAIN_PROCESS_LISTENER_EVENTS = frozenset(
    {"main_process_start", "main_process_stop", "main_process_ready"}
)


def _warn_if_main_process_listeners_ignored(
    server_listeners: Optional[List[Tuple[Callable[..., Any], Text]]],
) -> None:
    """Warn when caller listeners target events Sanic never dispatches at N=1."""
    if not server_listeners:
        return
    ignored_hook_names = [
        event for _, event in server_listeners if event in _MAIN_PROCESS_LISTENER_EVENTS
    ]
    if not ignored_hook_names:
        return
    structlogger.warning(
        "serve.server_listeners.main_process_ignored_under_single_process",
        event_info=(
            "Sanic's single-process runner does not dispatch main_process_* "
            "events. Prefer before_server_start / after_server_start."
        ),
        ignored_hook_names=ignored_hook_names,
    )


def _wrap_channels_for_inspection(
    input_channels: List[InputChannel],
    *,
    voice: Optional[bool],
    server_url: Optional[Text],
    legacy: bool,
) -> List[InputChannel]:
    """Wrap input channels with the development inspector proxy."""
    return [
        DevelopmentInspectProxy(channel, voice, server_url=server_url, is_legacy=legacy)
        for channel in input_channels
    ]


async def _open_inspector_on_start(config: ServeConfig, app: Sanic) -> None:
    """Open the inspector UI once the server is accepting connections."""
    from rasa.cli.inspect import open_inspector_in_browser

    server_url = config.inspector_server_url
    if server_url == "0.0.0.0" or server_url is None:
        protocol = "https" if config.ssl_certificate else "http"
        server_url = constants.DEFAULT_SERVER_FORMAT.format(protocol, config.port)
    await open_inspector_in_browser(
        server_url,
        config.inspector_legacy,
        config.inspector_voice,
        _secret_value(config.auth_token),
    )


async def _load_agent_or_fail(
    config: ServeConfig,
    app: Sanic,
    loop: AbstractEventLoop,
) -> None:
    """Load the agent from picklable serve settings.

    Raises instead of ``os._exit`` so Sanic's worker manager can terminate the
    whole server instead of restart-looping a failing worker.
    """
    configuration = Configuration.get_instance()
    try:
        await load_agent_on_start(
            config.model_path,
            configuration.endpoints,
            config.remote_storage,
            configuration.available_agents,
            app,
            loop,
            validate_a2a_server=False,
        )
    except DetailedRasaException as error:
        structlogger.error(error.code, event_info=error.info, **error.ctx)
        raise
    except Exception as error:
        if logger.isEnabledFor(logging.DEBUG):
            raise
        logger.exception("Failed to load agent: %s", error)
        raise


def _serve_listeners(config: ServeConfig) -> List[Tuple[Callable[..., Any], Text]]:
    """Return lifecycle listeners for a worker-rebuilt Sanic app.

    Prefer ``before_server_start`` / ``after_server_start`` over ``main_process_*``
    for anything that must run in the process serving requests.
    ``main_process_ready`` is used only for one-shot parent actions (browser open)
    under ``Sanic.serve`` (N>1).
    """
    listeners: List[Tuple[Callable[..., Any], Text]] = [
        (_configure_async_logging, "before_server_start"),
        (partial(_load_agent_or_fail, config), "before_server_start"),
        (licensing.validate_limited_server_license, "after_server_start"),
        (start_marketplace_license_recheck, "after_server_start"),
        (close_resources, "after_server_stop"),
    ]
    if config.open_inspector_in_browser:
        # Parent-only: fires after the listen socket binds under Sanic.serve.
        listeners.append(
            (partial(_open_inspector_on_start, config), "main_process_ready")
        )
    return listeners


def create_app_for_serve(config: ServeConfig) -> Sanic:
    """Build a Sanic app for the primary process and each spawn worker.

    Must be module-level so ``Sanic.serve`` can pickle it via ``AppLoader``.
    Reconstructs ``Configuration`` and channels from paths — never from live
    objects captured in the parent process.
    """
    _bootstrap_serve_process(config)
    configuration = Configuration.get_instance()
    input_channels = create_input_channels(config.connector, configuration.credentials)
    if config.is_inspector_enabled:
        input_channels = _wrap_channels_for_inspection(
            input_channels,
            voice=config.inspector_voice,
            server_url=config.inspector_server_url,
            legacy=config.inspector_legacy,
        )

    rasa.core.utils.configure_file_logging(
        logger,
        config.log_file,
        config.use_syslog,
        config.syslog_address,
        config.syslog_port,
        config.syslog_protocol,
    )

    if config.enable_api:
        app = server.create_app(
            cors_origins=config.cors,
            auth_token=_secret_value(config.auth_token),
            response_timeout=config.response_timeout,
            jwt_secret=_secret_value(config.jwt_secret),
            jwt_private_key=_secret_value(config.jwt_private_key),
            jwt_method=config.jwt_method,
            endpoints=configuration.endpoints,
            sub_agents=configuration.available_agents,
            is_inspector_enabled=config.is_inspector_enabled,
        )
    else:
        app = _create_app_without_api(config.cors, config.is_inspector_enabled)

    _apply_runtime_app_settings(app, config)
    _register_input_channels(app, input_channels, config.route)

    if config.ssl_certificate:
        app.certloader_class = _RasaCertLoader

    for listener, event in _serve_listeners(config):
        app.register_listener(listener, event)

    rasa.utils.common.update_sanic_log_level(
        config.log_file,
        config.use_syslog,
        config.syslog_address,
        config.syslog_port,
        config.syslog_protocol,
    )
    return app


def _validate_unique_socketio_paths(channels: List[InputChannel]) -> None:
    """Reject two Socket.IO channels sharing one transport path.

    Each Socket.IO channel attaches its own ``socketio.AsyncServer`` to a Sanic
    route, and two servers cannot claim the same route. Left unchecked this
    surfaces at server start as a ``RouteExists`` error that names neither
    channel, so fail here with something actionable instead.

    Raises:
        RasaException: If two or more channels resolve to the same path.
    """
    channels_by_path: Dict[Text, List[Text]] = {}
    for input_channel in channels:
        path = getattr(input_channel, "socketio_path", None)
        if path:
            channels_by_path.setdefault(path, []).append(input_channel.name())

    for path, names in channels_by_path.items():
        if len(names) > 1:
            raise RasaException(
                f"Channels {', '.join(sorted(names))} are all configured to use "
                f"the Socket.IO path '{path}', but each Socket.IO channel needs "
                f"its own. Set a distinct 'socketio_path' for all but one of "
                f"them in your credentials file."
            )


def create_input_channels(
    channel: Optional[Text], credentials_config: Optional[CredentialsConfig]
) -> List[InputChannel]:
    """Instantiate the chosen input channel.

    Args:
        channel (optional): The name of the specific input channel to create.
        credentials_config: CredentialsConfig object containing channel credentials.

    Returns:
        A list of instantiated input channels. If a specific channel is provided,
        it returns a list with that single channel. If no channel is specified,
        it returns a list of all channels defined in the credentials file.
    """
    if credentials_config:
        all_credentials = credentials_config.channels
    else:
        all_credentials = {}
    if channel:
        if len(all_credentials) > 1:
            logger.info(
                "Connecting to channel '{}' which was specified by the "
                "'--connector' argument. Any other channels will be ignored. "
                "To connect to all given channels, omit the '--connector' "
                "argument.".format(channel)
            )
        return [
            _create_single_channel(
                channel,
                all_credentials.get(channel),
            )
        ]

    channels = [_create_single_channel(c, k) for c, k in all_credentials.items()]
    _validate_unique_socketio_paths(channels)
    return channels


def _create_single_channel(
    channel: Text,
    credentials: Optional[Dict[Text, Any]],
) -> Any:
    """Create a single input channel based on the channel name and credentials.

    Args:
        channel: The name of the input channel to create.
        credentials: The credentials for the input channel.

    Returns:
        An instance of the input channel class.

    Raises:
        RasaException: If the channel class cannot be found or instantiated.
    """
    from rasa.core.channels import BUILTIN_CHANNELS

    # Channels that have optional dependencies
    channels_with_optional_deps = {
        "facebook": "fbmessenger",
        "slack": "slack-sdk",
        "telegram": "aiogram",
        "twilio": "twilio",
        "twilio_voice": "twilio",
        "twilio_media_streams": "twilio",
        "webexteams": "webexpythonsdk",
        "vier_cvg": "cvg_sdk",
    }

    if channel in BUILTIN_CHANNELS:
        channel_class = BUILTIN_CHANNELS[channel]

        return channel_class.from_credentials(credentials)
    elif channel in channels_with_optional_deps:
        # Channel is known but not available due to missing dependency
        dependency = channels_with_optional_deps[channel]
        raise RasaException(
            f"Channel '{channel}' is not available "
            f"due to missing '{dependency}' dependency. "
            f"Please install the required extra by running: "
            f"pip install 'rasa-pro[channels]' OR "
            f"poetry add 'rasa-pro[channels]'"
        )
    else:
        # try to load channel based on class name
        try:
            input_channel_class = rasa.shared.utils.common.class_from_module_path(
                channel
            )

            return input_channel_class.from_credentials(credentials)
        except (AttributeError, ImportError):
            raise RasaException(
                f"Failed to find input channel class for '{channel}'. Unknown "
                f"input channel. Check your credentials configuration to "
                f"make sure the mentioned channel is not misspelled. "
                f"If you are creating your own channel, make sure it "
                f"is a proper name of a class in a module."
            )


def _create_app_without_api(
    cors: Optional[Union[Text, List[Text]]] = None, is_inspector_enabled: bool = False
) -> Sanic:
    app = Sanic("rasa_core_no_api", configure_logging=False)

    # Reset Sanic warnings filter that allows the triggering of Sanic warnings
    warnings.filterwarnings("ignore", category=DeprecationWarning, module=r"sanic.*")

    server.add_root_route(app, is_inspector_enabled)
    configure_cors(app, cors)
    return app


def _is_apple_silicon_system() -> bool:
    # check if the system is MacOS
    if platform.system().lower() != "darwin":
        return False
    # check for arm architecture, indicating apple silicon
    return platform.machine().startswith("arm") or os.uname().machine.startswith("arm")


def _serve_with_app_loader(
    serve_config: ServeConfig,
    *,
    interface: Text,
    port: int,
    number_of_workers: int,
) -> None:
    """Serve via AppLoader so spawn workers can rebuild the app."""
    loader = AppLoader(factory=partial(create_app_for_serve, serve_config))
    app = loader.load()
    protocol = "https" if serve_config.ssl_certificate else "http"
    logger.info(f"Starting Rasa server on {protocol}://{interface}:{port}")
    app.prepare(
        host=interface,
        port=port,
        backlog=int(os.environ.get(ENV_SANIC_BACKLOG, "100")),
        workers=number_of_workers,
        ssl=_build_worker_ssl(serve_config),
    )
    Sanic.serve(primary=app, app_loader=loader)


def configure_app(
    input_channels: Optional[List[InputChannel]] = None,
    cors: Optional[Union[Text, List[Text], None]] = None,
    auth_token: Optional[Text] = None,
    enable_api: bool = True,
    response_timeout: int = constants.DEFAULT_RESPONSE_TIMEOUT,
    jwt_secret: Optional[Text] = None,
    jwt_private_key: Optional[Text] = None,
    jwt_method: Optional[Text] = None,
    route: Optional[Text] = constants.DEFAULT_WEBHOOKS_PATH,
    port: int = constants.DEFAULT_SERVER_PORT,
    endpoints: Optional[AvailableEndpoints] = None,
    sub_agents: Optional[AvailableAgents] = None,
    log_file: Optional[Text] = None,
    conversation_id: Optional[Text] = uuid.uuid4().hex,
    use_syslog: bool = False,
    syslog_address: Optional[Text] = None,
    syslog_port: Optional[int] = None,
    syslog_protocol: Optional[Text] = None,
    request_timeout: Optional[int] = None,
    server_listeners: Optional[List[Tuple[Callable, Text]]] = None,
    use_uvloop: Optional[bool] = False,
    keep_alive_timeout: int = constants.DEFAULT_KEEP_ALIVE_TIMEOUT,
    is_inspector_enabled: bool = False,
    a2a_agent_card: Optional["AgentCard"] = None,
    a2a_config: Optional["A2AServerSettings"] = None,
) -> Sanic:
    """Build a Sanic app for the single-worker (``configure_app``) serve path.

    ``server_listeners`` are registered only on this in-process path. Under
    multi-worker spawn they are ignored (see ``serve_application``). Sanic's
    ``single_process=True`` runner does not dispatch ``main_process_*`` events,
    so prefer ``before_server_start`` / ``after_server_start``.
    """
    rasa.core.utils.configure_file_logging(
        logger, log_file, use_syslog, syslog_address, syslog_port, syslog_protocol
    )

    if enable_api:
        loader = AppLoader(
            factory=partial(
                server.create_app,
                cors_origins=cors,
                auth_token=auth_token,
                response_timeout=response_timeout,
                jwt_secret=jwt_secret,
                jwt_private_key=jwt_private_key,
                jwt_method=jwt_method,
                endpoints=endpoints,
                sub_agents=sub_agents,
                is_inspector_enabled=is_inspector_enabled,
            )
        )
    else:
        loader = AppLoader(factory=partial(_create_app_without_api, cors))

    app = loader.load()
    runtime_settings = ServeConfig(
        enable_api=enable_api,
        cors=cors,
        response_timeout=response_timeout,
        keep_alive_timeout=keep_alive_timeout,
        use_uvloop=bool(use_uvloop),
        is_inspector_enabled=is_inspector_enabled,
        port=port,
        conversation_id=conversation_id,
        request_timeout=request_timeout,
        route=route,
    )
    _apply_runtime_app_settings(app, runtime_settings)

    if a2a_config is not None:
        server.register_a2a_server(app, a2a_config, a2a_agent_card)

    if input_channels:
        _register_input_channels(app, input_channels, route)
    else:
        input_channels = []

    app.register_listener(_configure_async_logging, "before_server_start")

    if "cmdline" in {c.name() for c in input_channels}:
        cmdline_config = ServeConfig(
            port=port,
            conversation_id=conversation_id,
            request_timeout=request_timeout,
            connector="cmdline",
        )
        app.register_listener(
            partial(_run_cmdline_io, cmdline_config), "after_server_start"
        )

    if server_listeners:
        for listener, event in server_listeners:
            app.register_listener(listener, event)

    return app


def _warn_mantle_in_memory_lock_store(
    endpoints: Optional[AvailableEndpoints],
    model_path: Optional[Text] = None,
) -> None:
    """Warn a Mantle project that several workers would not share locks.

    The integrations overlay has already run by the time ``serve_application``
    is called. The requested worker count is read before
    ``number_of_sanic_workers`` clamps an in-memory lock store back to one.
    A non-integer ``SANIC_WORKERS`` counts as the default, so this warning
    stays quiet when the server will not start that many workers.
    """
    from rasa.cli.project_env import resolve_project_dir
    from rasa.mantle.config.runtime_endpoints import (
        warn_if_in_memory_lock_store_with_multiple_workers,
    )
    from rasa.shared.engine_version import is_mantle_cli_context

    if not is_mantle_cli_context(
        project_root=resolve_project_dir(),
        model_path=model_path,
    ):
        return
    try:
        worker_count = rasa.core.utils.requested_sanic_workers()
    except ValueError:
        worker_count = DEFAULT_SANIC_WORKERS
    warn_if_in_memory_lock_store_with_multiple_workers(
        endpoints.lock_store if endpoints is not None else None,
        worker_count=worker_count,
    )


def serve_application(
    model_path: Optional[Text] = None,
    channel: Optional[Text] = None,
    interface: Optional[Text] = constants.DEFAULT_SERVER_INTERFACE,
    port: int = constants.DEFAULT_SERVER_PORT,
    credentials: Optional[CredentialsConfig] = None,
    cors: Optional[Union[Text, List[Text]]] = None,
    auth_token: Optional[Text] = None,
    enable_api: bool = True,
    response_timeout: int = constants.DEFAULT_RESPONSE_TIMEOUT,
    jwt_secret: Optional[Text] = None,
    jwt_private_key: Optional[Text] = None,
    jwt_method: Optional[Text] = None,
    endpoints: Optional[AvailableEndpoints] = None,
    sub_agents: Optional[AvailableAgents] = None,
    sub_agents_path: Optional[Text] = None,
    remote_storage: Optional[StorageType] = None,
    log_file: Optional[Text] = None,
    ssl_certificate: Optional[Text] = None,
    ssl_keyfile: Optional[Text] = None,
    ssl_ca_file: Optional[Text] = None,
    ssl_password: Optional[Text] = None,
    conversation_id: Optional[Text] = uuid.uuid4().hex,
    use_syslog: Optional[bool] = False,
    syslog_address: Optional[Text] = None,
    syslog_port: Optional[int] = None,
    syslog_protocol: Optional[Text] = None,
    logging_config_file: Optional[Text] = None,
    loglevel: Optional[int] = None,
    request_timeout: Optional[int] = None,
    server_listeners: Optional[List[Tuple[Callable, Text]]] = None,
    inspect: Optional[bool] = False,
    voice: Optional[bool] = False,
    legacy: Optional[bool] = False,
    inspector_server_url: Optional[Text] = None,
    open_inspector_in_browser: Optional[bool] = False,
    project_root: Optional[Path] = None,
) -> None:
    """Run the API entrypoint.

    Custom ``server_listeners`` are honoured on the single-worker path only.
    When Sanic spawns workers they cannot be pickled across the boundary and
    are ignored with a warning — prefer inspect-via-config
    (``open_inspector_in_browser`` / ``is_inspector_enabled``) for the
    development inspector. Under ``single_process=True``, Sanic also does not
    dispatch ``main_process_*`` events.

    ``project_root`` locates ``integrations.yml`` for the Mantle A2A server
    block. When omitted it follows ``RASA_PROJECT_FOLDER``, then the working
    directory.
    """
    validate_marketplace_license()

    if project_root is None:
        from rasa.cli.project_env import resolve_project_dir

        project_root = resolve_project_dir()

    if not channel and not credentials:
        channel = "cmdline"

    input_channels = create_input_channels(channel, credentials)

    if inspect:
        logger.info("Starting development inspector.")
        input_channels = _wrap_channels_for_inspection(
            input_channels,
            voice=voice,
            server_url=inspector_server_url,
            legacy=bool(legacy),
        )

        # the inspector needs the api to retrieve slots and flows
        enable_api = True

    _warn_mantle_in_memory_lock_store(endpoints, model_path)
    number_of_workers = rasa.core.utils.number_of_sanic_workers(
        endpoints.lock_store if endpoints else None
    )
    if number_of_workers > 1 and "cmdline" in _channel_names(input_channels):
        structlogger.warning(
            "serve.cmdline.forces_single_worker",
            event_info=(
                "The cmdline connector cannot share stdin across Sanic workers. "
                "Falling back to a single worker."
            ),
            requested_workers=number_of_workers,
        )
        number_of_workers = 1

    from rasa.core.a2a_server.config import validate_a2a_server_sanic_workers_or_raise
    from rasa.core.a2a_server.startup import resolve_a2a_server_startup

    a2a_startup = resolve_a2a_server_startup(
        endpoints=endpoints, project_root=project_root, model_path=model_path
    )
    validate_a2a_server_sanic_workers_or_raise(
        a2a_startup.settings if a2a_startup else None,
        number_of_workers=number_of_workers,
    )

    if number_of_workers > 1 and server_listeners:
        structlogger.warning(
            "serve.server_listeners.ignored_under_spawn",
            event_info=(
                "Custom server listeners are not carried to Sanic spawn workers "
                "and will be ignored. Prefer inspect-via-config for the "
                "development inspector."
            ),
            listener_count=len(server_listeners),
        )
    elif number_of_workers == 1:
        _warn_if_main_process_listeners_ignored(server_listeners)

    if not inspect:
        telemetry.track_server_start(
            input_channels, endpoints, model_path, number_of_workers, enable_api
        )

    if number_of_workers > 1:
        serve_config = build_serve_config(
            model_path=model_path,
            connector=channel,
            credentials=credentials,
            endpoints=endpoints,
            sub_agents_path=sub_agents_path,
            cors=cors,
            auth_token=auth_token,
            enable_api=enable_api,
            response_timeout=response_timeout,
            jwt_secret=jwt_secret,
            jwt_private_key=jwt_private_key,
            jwt_method=jwt_method,
            remote_storage=remote_storage,
            log_file=log_file,
            conversation_id=conversation_id,
            use_syslog=bool(use_syslog),
            syslog_address=syslog_address,
            syslog_port=syslog_port,
            syslog_protocol=syslog_protocol,
            logging_config_file=logging_config_file,
            log_level=loglevel,
            request_timeout=request_timeout,
            is_inspector_enabled=bool(inspect),
            inspector_voice=bool(voice),
            inspector_legacy=bool(legacy),
            inspector_server_url=inspector_server_url,
            open_inspector_in_browser=bool(open_inspector_in_browser),
            port=port,
            ssl_certificate=ssl_certificate,
            ssl_keyfile=ssl_keyfile,
            ssl_ca_file=ssl_ca_file,
            ssl_password=ssl_password,
            observability=applied_process_observability(),
        )
        structlogger.debug(
            "serve.config.built",
            enable_api=serve_config.enable_api,
            endpoints_path=serve_config.endpoints_path,
            has_endpoints_snapshot=serve_config.endpoints_snapshot is not None,
            credentials_path=serve_config.credentials_path,
            has_sub_agents_path=serve_config.sub_agents_path is not None,
            connector=serve_config.connector,
            number_of_workers=number_of_workers,
            has_ssl=serve_config.ssl_certificate is not None,
            is_inspector_enabled=serve_config.is_inspector_enabled,
        )
        _serve_with_app_loader(
            serve_config,
            interface=interface or constants.DEFAULT_SERVER_INTERFACE,
            port=port,
            number_of_workers=number_of_workers,
        )
        return

    if a2a_startup is not None:
        from rasa.core.a2a_server.bootstrap import resolve_agent_card

        _a2a_config = a2a_startup.settings
        _a2a_scheme = _a2a_config.bind_scheme(cli_ssl=bool(ssl_certificate))
        _a2a_agent_card = resolve_agent_card(
            a2a_startup.agent_card_settings(),
            port=port,
            interface=interface,
            scheme=_a2a_scheme,
        )
    else:
        _a2a_agent_card = None
        _a2a_config = None

    app = configure_app(
        input_channels,
        cors,
        auth_token,
        enable_api,
        response_timeout,
        jwt_secret,
        jwt_private_key,
        jwt_method,
        port=port,
        endpoints=endpoints,
        sub_agents=sub_agents,
        log_file=log_file,
        conversation_id=conversation_id,
        use_syslog=use_syslog,
        syslog_address=syslog_address,
        syslog_port=syslog_port,
        syslog_protocol=syslog_protocol,
        request_timeout=request_timeout,
        server_listeners=server_listeners,
        is_inspector_enabled=inspect,
        a2a_agent_card=_a2a_agent_card,
        a2a_config=_a2a_config,
    )

    ssl_context = server.create_ssl_context(
        ssl_certificate, ssl_keyfile, ssl_ca_file, ssl_password
    )
    protocol = "https" if ssl_context else "http"

    logger.info(f"Starting Rasa server on {protocol}://{interface}:{port}")

    async def load_agent_and_check_failure(app: Sanic, loop: AbstractEventLoop) -> None:
        """Load agent and exit if it fails in non-debug mode."""
        try:
            await load_agent_on_start(
                model_path,
                endpoints,
                remote_storage,
                sub_agents,
                app,
                loop,
                validate_a2a_server=False,
            )
        except DetailedRasaException as e:
            # Match ``rasa.__main__`` handling: actionable message, no traceback.
            structlogger.error(e.code, event_info=e.info, **e.ctx)
            os._exit(1)
        except Exception as e:
            is_debug = logger.isEnabledFor(logging.DEBUG)
            if is_debug:
                raise e  # show traceback in debug
            # non-debug: log and exit without starting server
            logger.error(f"Failed to load agent: {e}")
            os._exit(1)  # Any other exit method would show a traceback.

    app.register_listener(load_agent_and_check_failure, "before_server_start")

    if open_inspector_in_browser:
        browser_config = ServeConfig(
            port=port,
            conversation_id=conversation_id,
            inspector_server_url=inspector_server_url,
            inspector_legacy=bool(legacy),
            inspector_voice=bool(voice),
            auth_token=SecretStr(auth_token) if auth_token else None,
            ssl_certificate=ssl_certificate,
        )
        app.register_listener(
            partial(_open_inspector_on_start, browser_config), "after_server_start"
        )

    if a2a_startup is not None and _a2a_config is not None:
        from rasa.core.a2a_server.startup import bind_a2a_server_to_loaded_model

        a2a_bind_scheme = _a2a_config.bind_scheme(
            cli_ssl=bool(ssl_certificate), agent_card=_a2a_agent_card
        )

        async def init_a2a_agent_executor(
            running_app: Sanic, _loop: AbstractEventLoop
        ) -> None:
            """Bind A2A to the loaded model; exit on an expected startup failure."""
            try:
                await bind_a2a_server_to_loaded_model(
                    running_app,
                    a2a_startup,
                    port=port,
                    interface=interface,
                    scheme=a2a_bind_scheme,
                )
            except DetailedRasaException as e:
                structlogger.error(e.code, event_info=e.info, **e.ctx)
                os._exit(1)

        app.register_listener(init_a2a_agent_executor, "after_server_start")

    app.register_listener(
        licensing.validate_limited_server_license, "after_server_start"
    )

    app.register_listener(start_marketplace_license_recheck, "after_server_start")

    app.register_listener(close_resources, "after_server_stop")

    rasa.utils.common.update_sanic_log_level(
        log_file, use_syslog, syslog_address, syslog_port, syslog_protocol
    )

    # Single-worker stays in-process; multi-worker uses AppLoader + Sanic.serve.
    app.run(
        host=interface,
        port=port,
        ssl=ssl_context,
        backlog=int(os.environ.get(ENV_SANIC_BACKLOG, "100")),
        workers=number_of_workers,
        single_process=True,
    )


# noinspection PyUnusedLocal
async def load_agent_on_start(
    model_path: Text,
    endpoints: AvailableEndpoints,
    remote_storage: Optional[StorageType],
    sub_agents: Optional[AvailableAgents],
    app: Sanic,
    loop: AbstractEventLoop,
    *,
    validate_a2a_server: bool = True,
) -> Agent:
    """Load an agent.

    Used to be scheduled on server start
    (hence the `app` and `loop` arguments).

    ``validate_a2a_server`` is false on the ``rasa run`` path: the A2A settings
    were bound from the project layout before the model loaded, and
    ``bind_a2a_server_to_loaded_model`` checks the session config against
    those. A missing block means no routes and no session check.
    """
    app.ctx.agent = await agent.load_agent(
        model_path=model_path,
        remote_storage=remote_storage,
        endpoints=endpoints,
        sub_agents=sub_agents,
        loop=loop,
        validate_a2a_server=validate_a2a_server,
    )

    logger.info("Rasa server is up and running.")
    return app.ctx.agent


async def close_resources(app: Sanic, loop: AbstractEventLoop) -> None:
    """Gracefully closes resources when shutting down server.

    Buffered spans and metrics are flushed last, even when no agent loaded.

    Args:
        app: The Sanic application.
        loop: The current Sanic worker event loop.
    """
    try:
        import litellm

        await litellm.close_litellm_async_clients()  # type: ignore[no-untyped-call]
    except Exception:
        logger.warning("Failed to close litellm async clients.")

    if executor := getattr(app.ctx, "a2a_agent_executor", None):
        await executor.close()

    try:
        await _close_agent(app)
    finally:
        await flush_process_observability()


async def _close_agent(app: Sanic) -> None:
    """Close the agent, its event broker, and its privacy manager."""
    current_agent = getattr(app.ctx, "agent", None)
    if not current_agent:
        logger.debug("No agent found when shutting down server.")
        return

    await current_agent.close()

    event_broker = current_agent.tracker_store.event_broker
    if event_broker:
        await event_broker.close()

    current_agent.stop_privacy_manager()
